                    new_list.append(float(item) * 2)
                elif isinstance(item, str):
                    # Try to extract number from string using regex
                    match = re.search(r'-?\d+\.?\d*', item)
                    if match:
                        try:
                            num = float(match.group())
                            new_list.append(num * 2)
                        except ValueError:
                            new_list.append(item)
                    else:
                        new_list.append(item)
                else:
                    new_list.append(item)
            normalized_data[key] = new_list
        elif isinstance(value, str):
            # Try to extract number from string using regex
            match = re.search(r'-?\d+\.?\d*', value)
            if match:
                try:
                    num = float(match.group())
                    normalized_data[key] = num * 2
                except ValueError:
                    normalized_data[key] = value
            else:
                normalized_data[key] = value
        else:
            normalized_data[key] = value

    # Create DataFrame from normalized dictionary
    try:
        # Check if all values are lists of the same length or scalars
        # For DataFrame creation, we need consistent structure
        # If values are lists, they should be of the same length
        # If values are scalars, they become single-row DataFrame

        # Determine if we have list values
        has_lists = any(isinstance(v, list) for v in normalized_data.values())
        has_scalars = any(not isinstance(v, list) for v in normalized_data.values())

        if has_lists and has_scalars:
            # Mixed types - try to handle by converting scalars to single-element lists
            max_len = 0
            for v in normalized_data.values():
                if isinstance(v, list):
                    max_len = max(max_len, len(v))

            if max_len == 0:
                return pd.DataFrame()

            # Convert all values to lists of length max_len
            adjusted_data = {}
            for key, value in normalized_data.items():
                if isinstance(value, list):
                    if len(value) < max_len:
                        # Pad with None or repeat? Let's pad with None
                        adjusted_data[key] = value + [None] * (max_len - len(value))
                    else:
                        adjusted_data[key] = value[:max_len]
                else:
                    # Scalar - repeat to match max_len or just put in first position
                    adjusted_data[key] = [value] + [None] * (max_len - 1)

            df = pd.DataFrame(adjusted_data)
        elif has_lists:
            # All values are lists
            lengths = [len(v) for v in normalized_data.values() if isinstance(v, list)]
            if not lengths:
                return pd.DataFrame()
            max_len = max(lengths)
            if max_len == 0:
                return pd.DataFrame()

            adjusted_data = {}
            for key, value in normalized_data.items():
                if isinstance(value, list):
                    if len(value) < max_len:
                        adjusted_data[key] = value + [None] * (max_len - len(value))
                    else:
