import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    """
    Executes a given bash script and returns the CPU and memory usage of the script's process.

    Args:
        script_path: Path to the bash script to execute.
        timeout: Maximum time in seconds to wait for the script to complete.

    Returns:
        A dictionary containing:
        'CPU Usage': The accumulated CPU usage in percentage.
        'Memory Usage': The accumulated memory usage in bytes.
    """
    # Check if the script path exists
    if not os.path.exists(script_path):
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    # Start the subprocess
    try:
        proc = subprocess.Popen(
            ['bash', script_path],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
    except Exception:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    pid = proc.pid
    total_cpu_usage = 0.0
    total_memory_usage = 0

    start_time = time.time()
    last_cpu_times = None
    last_memory_rss = 0

    try:
        ps_proc = psutil.Process(pid)
    except (psutil.NoSuchProcess, psutil.AccessDenied):
        # Process already exited or not accessible
        proc.wait()
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    # Get initial CPU times and memory
    try:
        cpu_times = ps_proc.cpu_times()
        last_cpu_times = (cpu_times.user, cpu_times.system)
        last_memory_rss = ps_proc.memory_info().rss
    except (psutil.NoSuchProcess, psutil.AccessDenied):
        proc.wait()
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    while True:
        # Check if process is still running
        try:
            status = ps_proc.status()
            if status == psutil.STATUS_ZOMBIE:
                break
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break

        # Check timeout
        elapsed = time.time() - start_time
        if elapsed > timeout:
            # Terminate the process
            try:
                ps_proc.terminate()
                ps_proc.wait(timeout=1)
            except (psutil.NoSuchProcess, psutil.AccessDenied, subprocess.TimeoutExpired):
                try:
                    ps_proc.kill()
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pass
            break

        # Get current CPU times and memory
        try:
            cpu_times = ps_proc.cpu_times()
            current_cpu = (cpu_times.user, cpu_times.system)
            current_memory_rss = ps_proc.memory_info().rss

            # Calculate CPU usage increment
            if last_cpu_times is not None:
                cpu_delta = (current_cpu[0] - last_cpu_times[0]) + (current_cpu[1] - last_cpu_times[1])
                total_cpu_usage += cpu_delta * 100  # Convert to percentage

            # Calculate memory usage increment (sum of RSS increments)
            if current_memory_rss > last_memory_rss:
                total_memory_usage += current_memory_rss - last_memory_rss

            last_cpu_times = current_cpu
            last_memory_rss = current_memory_rss
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break

        # Small sleep to avoid busy waiting
        time.sleep(0.1)

    # Wait for the process to complete if it hasn't already
    try:
        proc.wait(timeout=1)
    except subprocess.TimeoutExpired:
        try:
            proc.kill()
            proc.wait()
        except Exception:
            pass

    return {'CPU Usage': total_cpu_usage, 'Memory Usage': total_memory_usage}

