import json

def task_func(json_str, filename, sheet_name="sheet1"):
    """
    Convert JSON strings to an Excel file, including handling empty JSON arrays.

    Parameters:
    json_str (str, bytes, or bytearray): The JSON string to convert.
    filename (str): The name of the Excel file to create.
    sheet_name (str): The name of the sheet in the Excel file.

    Returns:
    str: The absolute path of the created Excel file.

    Raises:
    ValueError: If json_str is not valid JSON.
    TypeError: If json_str is not a string, bytes, or bytearray.
    Exception: For other general errors related to file writing.
    """
    # Check type of json_str
    if not isinstance(json_str, (str, bytes, bytearray)):
        raise TypeError("json_str must be a string, bytes, or bytearray")

    # Parse JSON
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e}")

    # Handle empty array case
    if isinstance(data, list) and len(data) == 0:
        # Create an empty DataFrame
        df = pd.DataFrame()
    elif isinstance(data, list):
        # Convert list of dicts to DataFrame
        try:
            df = pd.DataFrame(data)
        except Exception as e:
            raise Exception(f"Error creating DataFrame from JSON data: {e}")
    elif isinstance(data, dict):
        # Convert dict to DataFrame
        try:
            df = pd.DataFrame([data])
        except Exception as e:
            raise Exception(f"Error creating DataFrame from JSON data: {e}")
    else:
        # For other JSON types (string, number, boolean, null), create a single-cell DataFrame
        try:
            df = pd.DataFrame([[data]], columns=["value"])
        except Exception as e:
            raise Exception(f"Error creating DataFrame from JSON data: {e}")

    # Write to Excel file
    try:
        # Ensure the directory exists
        dir_name = os.path.dirname(os.path.abspath(filename))
        if dir_name and not os.path.exists(dir_name):
            os.makedirs(dir_name)

        # Write DataFrame to Excel
        df.to_excel(filename, sheet_name=sheet_name, index=False)

        # Return absolute path
        return os.path.abspath(filename)
    except Exception as e:
        raise Exception(f"Error writing to Excel file: {e}")

